// Monta o corpo do evento do Google Calendar.
//
// conferenceData.createRequest é o que faz o Google GERAR o link do Meet. Sem
// ele o evento nasce sem sala; sem o parâmetro conferenceDataVersion=1 na URL
// (ver o nó seguinte) o Google IGNORA este bloco em silêncio — o evento é criado
// certinho, só que sem Meet nenhum, e o sintoma é "cadê o link?".
//
// requestId precisa ser único por evento: reenviar o MESMO requestId devolve a
// mesma sala em vez de criar outra.
const b = $('Webhook QS (qs-agenda-meet)').first().json.body || {};
const cfg = $('Config da agenda').first().json;

if (!b.inicio || !b.fim) {
  throw new Error('QS mandou reunião sem início/fim — evento não criado.');
}

const convidados = Array.isArray(b.convidados) ? b.convidados.filter(Boolean) : [];

return [{ json: {
  calendarId: cfg.CALENDAR_ID || 'primary',
  meeting_id: b.meeting_id,
  evento: {
    summary: b.titulo || 'Reunião',
    description: b.descricao || '',
    start: { dateTime: b.inicio, timeZone: b.timezone || 'America/Sao_Paulo' },
    end:   { dateTime: b.fim,    timeZone: b.timezone || 'America/Sao_Paulo' },
    attendees: convidados.map((email) => ({ email })),
    conferenceData: {
      createRequest: {
        requestId: 'qs-' + String(b.meeting_id || Date.now()),
        conferenceSolutionKey: { type: 'hangoutsMeet' }
      }
    },
    reminders: { useDefault: false, overrides: [ { method: 'popup', minutes: 30 }, { method: 'email', minutes: 60 } ] }
  }
} }];

// O nó acima segue em frente mesmo com erro (onError) pra este nó poder dar uma
// mensagem que se entende. Sem isto, uma recusa do Google viraria execução verde
// e o sintoma seria "marquei ganho e não apareceu nada na agenda".
const r = $input.first().json;
const montado = $('Montar evento').first().json;

if (!r || r.error) {
  const e = r && r.error;
  const msg = (e && (e.message || e.status)) || 'resposta vazia';
  throw new Error('Google recusou a criação do evento: ' + msg);
}
if (!r.id) {
  throw new Error('Google respondeu sem id de evento.');
}

// hangoutLink é o link do Meet. Ele NÃO vem quando falta conferenceDataVersion=1
// ou quando a conta não tem permissão de criar conferência — devolvemos assim
// mesmo (o evento existe), e o QS mostra a reunião sem sala em vez de quebrar.
const meet = r.hangoutLink
  || (r.conferenceData && r.conferenceData.entryPoints || []).filter((p) => p.entryPointType === 'video').map((p) => p.uri)[0]
  || null;

return [{ json: {
  ok: true,
  meeting_id: montado.meeting_id,
  event_id: r.id,
  meet_link: meet,
  html_link: r.htmlLink || null
} }];
